export const primaryKeyToPublicKey = (primaryKey) => {
    if (isPrimaryKey(primaryKey) === false) {
        throw new Error("Invalid PrimaryKey");
    }
    const [primaryChars, flag] = splitPrimaryKey(primaryKey);
    return prependFlagToPublicKeyX(primaryCharsToUint8Array(primaryChars), flag);
};
